    template <typename scalar_t>
    __device__ __forceinline__ scalar_t clip_grad(scalar_t a) {
        if (is_clip_grad) {
            if (abs(a) >= 1e-2f) {
                return a;
            }

            if (abs(a) < 1e-2f && abs(a) >= 1e-4f)
                return max(abs(a), 1e-2f) * sign(a);

            if (abs(a) < 1e-4f && abs(a) >= 1e-6f)
                return max(abs(a), 1e-3f) * sign(a);

            return a;
        }

        return a;
    }

